(*
 S04 称重零点漂移补偿
 扫描周期：20 ms

 冲突/不可达报告：
 1) C2 要求 G(DriftAlarm -> driftOut)，即报警时偏差必须超过 ±200；
    但控制要求 K3 与 C6/C7 采用 ±150 滞回保持，允许偏差在 151..199 区间继续报警。
    本实现按 K3/C6/C7 的滞回语义执行，因此 C2 不能同时满足。
 2) Status 16#8402 要求 RawWeight 超出 -32768..32767 的可用段；
    但 RawWeight 的外部类型为 INT，IEC INT 的可表示范围即 -32768..32767。
    该超量程条件在本接口下不可由输入触发/不可检测，代码保留分支但无实际可触发路径。
 3) C10 要求首周期 CompensatedWeight=0.0，而 C4 要求每周期
    CompensatedWeight=(RawWeight-ZeroOffset)*0.01；当首周期 RawWeight 非零时二者不能同时满足。
    本实现按 C4 每周期更新，上电初态由变量默认初始化满足。
*)
FUNCTION_BLOCK FB_S04
VAR_INPUT
    RawWeight : INT;
    ZeroBtn : BOOL;
    CalibWeight : REAL;
END_VAR
VAR_OUTPUT
    CompensatedWeight : REAL;
    ZeroOffset : INT;
    DriftAlarm : BOOL;
    Status : WORD;
END_VAR
VAR
    ZeroBtnLast : BOOL := FALSE;
    delta : DINT;
END_VAR

(* CalibWeight 仅作显示，不参与控制逻辑 *)

(* ZeroBtn 上升沿：采样当前 RawWeight 为零点，并清漂移报警 *)
IF ZeroBtn AND NOT ZeroBtnLast THEN
    ZeroOffset := RawWeight;
    DriftAlarm := FALSE;
END_IF;
ZeroBtnLast := ZeroBtn;

(* 每扫描周期按当前 RawWeight 和 ZeroOffset 计算补偿重量，单位 kg *)
CompensatedWeight := (INT_TO_REAL(RawWeight) - INT_TO_REAL(ZeroOffset)) * 0.01;

(* 漂移判据：±200 置位，回到 ±150 以内复位，形成 50 单位滞回 *)
delta := INT_TO_DINT(RawWeight) - INT_TO_DINT(ZeroOffset);
IF (delta >= 200) OR (delta <= -200) THEN
    DriftAlarm := TRUE;
ELSIF DriftAlarm AND (delta <= 150) AND (delta >= -150) THEN
    DriftAlarm := FALSE;
END_IF;

(* 状态码：超量程优先于零点漂移 *)
IF (INT_TO_DINT(RawWeight) < -32768) OR (INT_TO_DINT(RawWeight) > 32767) THEN
    Status := WORD#16#8402;
ELSIF DriftAlarm THEN
    Status := WORD#16#8401;
ELSE
    Status := WORD#16#0000;
END_IF;

END_FUNCTION_BLOCK
